/**
 * Application-wide constants
 */

// API Configuration
// Bundled pronunciation dictionary, generated by scripts/build-cmudict.js; the online API is the fallback
export const CMUDICT_PATH = 'cmudict-ipa.txt';
export const DICTIONARY_API_BASE_URL = 'https://api.dictionaryapi.dev/api/v2/entries/en';

// Translation Configuration
export const GOOGLE_TRANSLATE_URL = 'https://translate.googleapis.com/translate_a/single';
// Undocumented client strings; Google gates the endpoint per value, so rotate on refusal
export const GOOGLE_TRANSLATE_CLIENTS = ['dict-chrome-ex', 'gtx'];
export const MYMEMORY_TRANSLATE_URL = 'https://api.mymemory.translated.net/get';
export const MYMEMORY_MAX_CHARS = 500;
export const TRANSLATION_MAX_CHARS = 5000;
// Longer selections are cut to this, so the popup stays quick to build and can still be translated
export const SELECTION_MAX_CHARS = TRANSLATION_MAX_CHARS;
export const ENGLISH_LANG = 'en';
// Selected Vietnamese text is translated into English instead of into the chosen language
export const VIETNAMESE_LANG = 'vi';
export const DICTIONARY_MAX_MEANINGS = 5;
export const TRANSLATION_OFF = 'off';
export const DEFAULT_TARGET_LANGUAGE = 'vi';

// What happens when text is selected
export const POPUP_MODES = {
  // Open the pronunciation popup right away
  IMMEDIATE: 'immediate',
  // Show a small icon by the selection; clicking it opens the popup
  ICON: 'icon',
  // Do nothing
  NONE: 'none'
} as const;
export type PopupMode = typeof POPUP_MODES[keyof typeof POPUP_MODES];
export const DEFAULT_POPUP_MODE: PopupMode = POPUP_MODES.IMMEDIATE;

// Sites the dictionary link can open a word on; the word is appended to the URL
export const DICTIONARY_SITES = {
  'dictionary-com': { name: 'Dictionary.com', url: 'https://www.dictionary.com/browse/' },
  cambridge: { name: 'Cambridge Dictionary', url: 'https://dictionary.cambridge.org/dictionary/english/' }
} as const;
export type DictionarySite = keyof typeof DICTIONARY_SITES;
export const DEFAULT_DICTIONARY_SITE: DictionarySite = 'dictionary-com';

// Color theme for Sayly's popups and pages; "system" follows the browser's light/dark preference
export const THEMES = {
  SYSTEM: 'system',
  LIGHT: 'light',
  DARK: 'dark'
} as const;
export type Theme = typeof THEMES[keyof typeof THEMES];
export const DEFAULT_THEME: Theme = THEMES.SYSTEM;

// YouTube watch pages: shortcuts to hear the current sentence again or move to the next one, using the
// video's captions. Without captions they skip back or forward by the chosen number of seconds instead.
// A and D, which YouTube leaves free (it takes ←/→ for 5s and J/L for 10s); lowercase key values
export const YOUTUBE_SEEK_KEYS = {
  BACK: 'a',
  FORWARD: 'd'
} as const;
// A sentence plays from a little before its first word, so the word isn't clipped
export const SENTENCE_LEAD_MS = 250;
// Pressing back again within this long goes to the sentence before
export const SENTENCE_RESTART_WINDOW_MS = 1000;
// For captions without punctuation: a pause this long ends a sentence, and a sentence this long ends
// at the next caption line
export const CAPTION_SENTENCE_GAP_MS = 1000;
export const CAPTION_SENTENCE_MAX_MS = 10000;
// Videos whose caption sentences are kept
export const CAPTION_CACHE_SIZE = 10;
export const YOUTUBE_SEEK_MIN_SECONDS = 1;
export const YOUTUBE_SEEK_MAX_SECONDS = 60;
export const DEFAULT_YOUTUBE_SEEK_SECONDS = 2;

// Text-to-speech: Google Translate's voice (undocumented endpoint; tw-ob is the client it answers)
export const GOOGLE_TTS_URL = 'https://translate.google.com/translate_tts';
export const GOOGLE_TTS_CLIENT = 'tw-ob';
export const GOOGLE_TTS_MAX_CHARS = 200;
export const GOOGLE_TTS_SLOW_SPEED = '0.24';
export const TTS_LANG = 'en';
export const OFFSCREEN_DOCUMENT_PATH = 'offscreen.html';

// Runtime message actions (Google TTS ones live in speech/tts-messages.ts)
export const MESSAGE_ACTIONS = {
  // Content script → background
  TRANSLATE: 'translate',
  LOOKUP_IPA: 'lookup-ipa',
  // Extension popup → content script
  ENABLE: 'enable',
  DISABLE: 'disable'
} as const;

// Background caches for repeated lookups (entries; the service worker's memory is dropped when it idles out)
export const TRANSLATION_CACHE_SIZE = 200;
export const IPA_CACHE_SIZE = 500;
// Downloaded Google TTS audio (one entry per chunk and speed), kept this long for replays
export const TTS_AUDIO_CACHE_SIZE = 100;
export const TTS_AUDIO_CACHE_TTL_MS = 10 * 60 * 1000;

// CSS Classes
export const POPUP_CSS_CLASS = 'elang-pronunciation-popup';
// The bar by the selection in "display icon" mode: open-popup button, plus copy button unless turned off
export const TRIGGER_CSS_CLASS = 'elang-trigger';
// Added to the popup and selection bar when they should be dark
export const DARK_THEME_CSS_CLASS = 'elang-theme-dark';

// UI Timing (milliseconds)
export const SELECTION_DELAY_MS = 10;
// How long the copy button shows its done state
export const COPY_FEEDBACK_MS = 1200;
// A press that moves less than this is a click, not a drag that selects text
export const CLICK_MAX_MOVE_PX = 4;
export const POPUP_POSITION_OFFSET_PX = 10;
export const POPUP_EDGE_MARGIN_PX = 10;
export const VOICE_LOAD_TIMEOUT_MS = 3000;
export const WORD_BUBBLE_GAP_PX = 6;
export const SPEECH_FALLBACK_TIMEOUT_MS = 10000;
// Playing the same text again within this window plays it slowly
export const SLOW_REPEAT_WINDOW_MS = 30000;

// Voice Configuration
export const PREFERRED_VOICE_LANG = 'en-US';
// The browser voice's slow repeat plays at this fraction of the chosen speed
export const SLOW_SPEECH_RATE = 0.7;
// Speech speed choices (playback rate; applies to Google's voice and browser voices)
export const SPEECH_SPEEDS = [0.5, 0.75, 1, 1.25, 1.5] as const;
export const DEFAULT_SPEECH_SPEED = 1;
// The Voice setting: automatic, Google's voice, or a browser voice's voiceURI
export const AUTO_VOICE = 'auto';
export const GOOGLE_VOICE = 'google';
export const DEFAULT_VOICE = AUTO_VOICE;
// Automatic picks the first of Microsoft's natural en-US voices that is installed (Edge has them),
// else Google's voice; matched as "Microsoft <name> Online (Natural)", best first
export const NATURAL_VOICE_NAMES = ['Christopher', 'Ava', 'Jenny', 'Aria', 'Andrew', 'Emma', 'Guy', 'Brian'] as const;
// Played by the options page's voice preview
export const VOICE_SAMPLE_TEXT = 'The quick brown fox jumps over the lazy dog.';
